"""The `stockroom` command."""

import csv
import io
import json
import os
import sys
from typing import List, Optional

from . import orders as orders_mod
from .parsing import (
    WHOLE_RE,
    Movement,
    ParseError,
    check_balances,
    normalize_sku,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
)
from .pricing import Quote
from .shelves import (
    append_lines,
    buy_quantity,
    format_movement,
    history,
    signed,
    status,
    stock_levels,
)

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (allowed positional counts, allowed options)
COMMANDS = {
    "stock": ((0,), {"--json"}),
    "low": ((0,), {"--json"}),
    "history": ((1,), {"--json"}),
    "receive": ((3, 4), set()),
    "ship": ((3, 4), set()),
    "quote": ((1,), {"--json"}),
    "fulfil": ((2,), set()),
    "invoice": ((1,), {"--json"}),
    "report": ((0,), {"--format"}),
}
RAW_COMMANDS = {"receive", "ship", "fulfil"}
FORMATS = ("text", "csv", "json")
USAGE = "usage: stockroom [--dir DIR] {stock,low,history,receive,ship,quote,fulfil,invoice,report} ..."


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class ReadError(Exception):
    """A file that cannot be read (exit 2)."""


class Refused(Exception):
    """A data-file mistake or refused request (exit 1)."""


class Args:
    def __init__(self):
        self.dir = "."
        self.command: Optional[str] = None
        self.positional: List[str] = []
        self.json = False
        self.format = "text"


def parse_args(argv: List[str]) -> Args:
    args = Args()
    rest: List[str] = []
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("option --dir needs a value")
            args.dir = argv[i + 1]
            i += 2
            continue
        if token.startswith("--dir="):
            args.dir = token[len("--dir="):]
            i += 1
            continue
        rest.append(token)
        i += 1
    if args.dir == "":
        raise UsageError("option --dir needs a non-empty value")

    before: List[str] = []
    after: List[str] = []
    for token in rest:
        if args.command is None and not token.startswith("-"):
            args.command = token
        elif args.command is None:
            before.append(token)
        else:
            after.append(token)
    if args.command is None:
        if before:
            raise UsageError("unknown option {}".format(before[0]))
        raise UsageError("no command given")
    if args.command not in COMMANDS:
        raise UsageError("unknown command {!r}".format(args.command))
    counts, options = COMMANDS[args.command]

    if args.command in RAW_COMMANDS:
        if before:
            raise UsageError("unknown option {}".format(before[0]))
        args.positional = after
    else:
        tokens = before + after
        j = 0
        while j < len(tokens):
            token = tokens[j]
            if token.startswith("-") and token != "-":
                if token == "--json" and "--json" in options:
                    args.json = True
                elif token == "--format" and "--format" in options:
                    if j + 1 >= len(tokens):
                        raise UsageError("option --format needs a value")
                    args.format = tokens[j + 1]
                    j += 1
                    if args.format not in FORMATS:
                        raise UsageError("bad value for --format: {!r} (text, csv or json)".format(args.format))
                elif token.startswith("--format=") and "--format" in options:
                    args.format = token[len("--format="):]
                    if args.format not in FORMATS:
                        raise UsageError("bad value for --format: {!r} (text, csv or json)".format(args.format))
                else:
                    raise UsageError("unknown option {} for {}".format(token, args.command))
            else:
                args.positional.append(token)
            j += 1

    if len(args.positional) not in counts:
        raise UsageError("wrong number of arguments for {}".format(args.command))
    if args.command in ("receive", "ship", "fulfil"):
        date_text = args.positional[0] if args.command != "fulfil" else args.positional[1]
        if parse_date(date_text) is None:
            raise UsageError("bad date {!r} (expected YYYY-MM-DD)".format(date_text))
    return args


class Files:
    """Reads the data files of one folder."""

    def __init__(self, folder: str):
        if not os.path.isdir(folder):
            raise ReadError("{}: no such directory".format(folder))
        self.folder = folder

    def path(self, name: str) -> str:
        return os.path.join(self.folder, name)

    def text(self, name: str) -> str:
        try:
            with open(self.path(name), "rb") as fh:
                data = fh.read()
        except FileNotFoundError:
            if name == CATALOG:
                raise ReadError("{}: file not found".format(name))
            data = b""
        except OSError as exc:
            raise ReadError("{}: {}".format(name, exc.strerror or exc))
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ReadError("{}: not valid UTF-8 (byte {})".format(name, exc.start))


def load(files: Files, need_movements: bool, need_orders: bool):
    """Read then parse the needed files; returns (catalog, movements, orders)."""
    catalog_text = files.text(CATALOG)
    movements_text = files.text(MOVEMENTS) if need_movements else None
    orders_text = files.text(ORDERS) if need_orders else None
    name = CATALOG
    try:
        catalog = parse_catalog(catalog_text)
        movements = None
        orders = None
        if movements_text is not None:
            name = MOVEMENTS
            movements = parse_movements(movements_text, catalog)
        if orders_text is not None:
            name = ORDERS
            orders = parse_orders(orders_text, catalog)
    except ParseError as exc:
        raise Refused("{}: {}".format(name, exc))
    return catalog, movements, orders


def dump_json(obj) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


def find_order(order_list, text: str):
    wanted = text.upper()
    for order in order_list:
        if order.id == wanted:
            return order
    raise Refused("{}: unknown order {}".format(ORDERS, text))


def quote_text(header: str, quote: Quote) -> str:
    out = [header]
    for ln in quote.lines:
        out.append("{} {} {} {} {} {}".format(ln.sku, ln.quantity, ln.unit, ln.gross, ln.discount, ln.net))
    out.append("subtotal {}".format(quote.subtotal))
    out.append("order discount {}".format(quote.order_discount))
    out.append("tax {}".format(quote.tax))
    out.append("total {}".format(quote.total))
    return lines_out(out)


def quote_json(order, quote: Quote) -> str:
    return dump_json(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": ln.sku,
                    "quantity": ln.quantity,
                    "unit": str(ln.unit),
                    "gross": str(ln.gross),
                    "discount": str(ln.discount),
                    "net": str(ln.net),
                }
                for ln in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        }
    )


def cmd_stock(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        p = catalog[sku]
        rows.append({"sku": sku, "name": p.name, "onhand": levels[sku], "status": status(levels[sku], p.reorder)})
    if args.json:
        return dump_json(rows)
    return lines_out(["{} {} {} {}".format(r["sku"], r["onhand"], r["status"], r["name"]) for r in rows])


def cmd_low(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        p = catalog[sku]
        onhand = levels[sku]
        if status(onhand, p.reorder) in ("low", "out"):
            rows.append({"sku": sku, "onhand": onhand, "reorder": p.reorder, "buy": buy_quantity(onhand, p.reorder)})
    if args.json:
        return dump_json(rows)
    return lines_out(["{} {} {} {}".format(r["sku"], r["onhand"], r["reorder"], r["buy"]) for r in rows])


def cmd_history(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    sku = normalize_sku(args.positional[0])
    if sku is None or sku not in catalog:
        raise Refused("{}: unknown SKU {}".format(CATALOG, args.positional[0]))
    rows = history(sku, movements)
    if args.json:
        return dump_json(
            [
                {"date": m.date.isoformat(), "delta": signed(m.quantity), "balance": bal, "note": m.note}
                for m, bal in rows
            ]
        )
    out = []
    for m, bal in rows:
        text = "{} {} {}".format(m.date.isoformat(), signed(m.quantity), bal)
        if m.note:
            text += " " + m.note
        out.append(text)
    return lines_out(out)


def cmd_move(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    date_text, sku_text, qty_text = args.positional[:3]
    note = args.positional[3] if len(args.positional) == 4 else ""
    date = parse_date(date_text)
    sku = normalize_sku(sku_text)
    if sku is None or sku not in catalog:
        raise Refused("{}: unknown SKU {}".format(CATALOG, sku_text))
    if not WHOLE_RE.match(qty_text) or int(qty_text) == 0:
        raise Refused("bad quantity {!r}: must be a whole number of one or more".format(qty_text))
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    note = note.strip(" \t")
    quantity = int(qty_text) if args.command == "receive" else -int(qty_text)
    new = Movement(date=date, sku=sku, quantity=quantity, note=note, line=0)
    try:
        check_balances(list(movements) + [new])
    except ParseError as exc:
        if exc.line == 0:
            raise Refused("{}: refused: stock of {} would go below zero".format(MOVEMENTS, sku))
        raise Refused(
            "{}: refused: stock of {} would go below zero at line {}".format(MOVEMENTS, sku, exc.line)
        )
    line = format_movement(date, sku, quantity, note)
    write(files, [line])
    return lines_out([line])


def write(files: Files, lines: List[str]) -> None:
    try:
        append_lines(files.path(MOVEMENTS), lines)
    except OSError as exc:
        raise ReadError("{}: {}".format(MOVEMENTS, exc.strerror or exc))


def cmd_quote(args: Args, files: Files) -> str:
    catalog, _, order_list = load(files, False, True)
    order = find_order(order_list, args.positional[0])
    quote = orders_mod.price_order(order, catalog)
    if args.json:
        return quote_json(order, quote)
    return quote_text("{} {} {}".format(order.id, order.date.isoformat(), order.customer), quote)


def cmd_fulfil(args: Args, files: Files) -> str:
    catalog, movements, order_list = load(files, True, True)
    order = find_order(order_list, args.positional[0])
    date = parse_date(args.positional[1])
    if date < order.date:
        raise Refused(
            "refused: {} is before the date of order {} ({})".format(date.isoformat(), order.id, order.date.isoformat())
        )
    result = orders_mod.fulfil(order, date, movements)
    if result.movements:
        write(files, result.movements)
    out = ["{} shipped {} backordered {}".format(ln.sku, ln.shipped, ln.backordered) for ln in result.lines]
    out.append("status {}".format(result.status))
    return lines_out(out)


def cmd_invoice(args: Args, files: Files) -> str:
    catalog, movements, order_list = load(files, True, True)
    order = find_order(order_list, args.positional[0])
    quote = orders_mod.invoice(order, catalog, movements)
    if quote is None:
        raise Refused("refused: nothing has shipped for order {} yet".format(order.id))
    if args.json:
        return quote_json(order, quote)
    return quote_text("invoice {} {} {}".format(order.id, order.date.isoformat(), order.customer), quote)


def cmd_report(args: Args, files: Files) -> str:
    catalog, movements, order_list = load(files, True, True)
    rows = []
    for r in orders_mod.report(order_list, catalog, movements):
        rows.append(
            {
                "order": r.order.id,
                "date": r.order.date.isoformat(),
                "customer": r.order.customer,
                "status": r.status,
                "ordered": r.ordered,
                "shipped": r.shipped,
                "quoted": str(r.quoted.total),
                "invoiced": str(r.invoiced.total) if r.invoiced else "0.00",
            }
        )
    if args.format == "json":
        return dump_json(rows)
    if args.format == "csv":
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buf.getvalue()
    return lines_out(
        [
            "{} {} {} {} {}/{} {} {}".format(
                r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"]
            )
            for r in rows
        ]
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def emit(text: str) -> None:
    buffer = getattr(sys.stdout, "buffer", None)
    if buffer is not None:
        sys.stdout.flush()
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        sys.stdout.write(text)
        sys.stdout.flush()


def error(message: str) -> None:
    text = "stockroom: {}\n".format(message)
    buffer = getattr(sys.stderr, "buffer", None)
    if buffer is not None:
        sys.stderr.flush()
        buffer.write(text.encode("utf-8", "backslashreplace"))
        buffer.flush()
    else:
        sys.stderr.write(text)
        sys.stderr.flush()


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parse_args(list(argv))
        files = Files(args.dir)
        output = HANDLERS[args.command](args, files)
    except UsageError as exc:
        error(str(exc))
        sys.stderr.write(USAGE + "\n")
        return 2
    except ReadError as exc:
        error(str(exc))
        return 2
    except Refused as exc:
        error(str(exc))
        return 1
    try:
        emit(output)
    except BrokenPipeError:
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError, io.UnsupportedOperation):
            pass
        return 0
    return 0
