"""Turning the three text files into Python objects."""

import datetime
import re
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Dict, Iterable, Iterator, List, Optional, Tuple

TAX_RATES = {
    "standard": Decimal("0.20"),
    "reduced": Decimal("0.05"),
    "zero": Decimal("0"),
}

WS = " \t"

SKU_RE = re.compile(r"^[A-Za-z]{2,4}-[0-9]{3}$")
PRICE_RE = re.compile(r"^[0-9]+(\.[0-9]{1,2})?$")
WHOLE_RE = re.compile(r"^[0-9]+$")
SIGNED_RE = re.compile(r"^[+-]?[0-9]+$")
DATE_RE = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$")
ORDER_RE = re.compile(r"^[Ss][Oo]-[0-9]+$")
FIELDS_RE = re.compile(r"[ \t]+")
MOVEMENT_RE = re.compile(r"^([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?$", re.S)


class ParseError(ValueError):
    """A mistake on a given line of a data file."""

    def __init__(self, line: int, reason: str):
        self.line = line
        self.reason = reason
        super().__init__("line {}: {}".format(line, reason))


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False)


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]]
    line: int = field(default=0, compare=False)


def iter_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield (line number, content) for every non-blank, non-comment line.

    Lines end only at LF (an optional CR before it is dropped); a leading BOM
    is ignored.
    """
    if text.startswith("﻿"):
        text = text[1:]
    if text == "":
        return
    parts = text.split("\n")
    if parts and parts[-1] == "":
        parts.pop()
    for number, raw in enumerate(parts, start=1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        stripped = raw.strip(WS)
        if stripped == "" or stripped.startswith("#"):
            continue
        yield number, raw


def parse_date(value: str) -> Optional[datetime.date]:
    """Return the date for a strict YYYY-MM-DD string, or None."""
    if not DATE_RE.match(value):
        return None
    try:
        return datetime.date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        return None


def normalize_sku(value: str) -> Optional[str]:
    """Return the upper-case SKU if the text is a well-formed SKU, else None."""
    if not SKU_RE.match(value):
        return None
    return value.upper()


def parse_catalog(text: str) -> Dict[str, Product]:
    """Parse catalog.txt into a dict of SKU -> Product, in file order."""
    catalog: Dict[str, Product] = {}
    for number, raw in iter_lines(text):
        fields = [f.strip(WS) for f in raw.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found {}".format(len(fields)))
        sku_text, name, price_text, reorder_text = fields[:4]
        sku = normalize_sku(sku_text)
        if sku is None:
            raise ParseError(number, "bad SKU {!r}".format(sku_text))
        if sku in catalog:
            raise ParseError(number, "duplicate SKU {}".format(sku))
        if name == "":
            raise ParseError(number, "empty product name")
        if not PRICE_RE.match(price_text):
            raise ParseError(number, "bad price {!r}".format(price_text))
        price = Decimal(price_text).quantize(Decimal("0.01"))
        if price < Decimal("0.01"):
            raise ParseError(number, "price must be at least 0.01")
        if not WHOLE_RE.match(reorder_text):
            raise ParseError(number, "bad reorder level {!r}".format(reorder_text))
        reorder = int(reorder_text)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(number, "bad tax band {!r}".format(fields[4]))
        catalog[sku] = Product(sku=sku, name=name, price=price, reorder=reorder, tax=tax)
    return catalog


def check_balances(movements: Iterable[Movement]) -> None:
    """Raise ParseError on the first movement that takes stock below zero.

    Movements count in date order; same-day movements keep their list order.
    """
    ordered = sorted(movements, key=lambda m: m.date)
    balance: Dict[str, int] = {}
    for m in ordered:
        new = balance.get(m.sku, 0) + m.quantity
        if new < 0:
            raise ParseError(
                m.line,
                "stock of {} would go below zero ({}) on {}".format(m.sku, new, m.date.isoformat()),
            )
        balance[m.sku] = new


def parse_movement_line(number: int, raw: str, catalog: Dict[str, Product]) -> Movement:
    match = MOVEMENT_RE.match(raw.strip(WS))
    if not match:
        raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
    date_text, sku_text, qty_text, note = match.groups()
    date = parse_date(date_text)
    if date is None:
        raise ParseError(number, "bad date {!r}".format(date_text))
    sku = normalize_sku(sku_text)
    if sku is None or sku not in catalog:
        raise ParseError(number, "unknown SKU {!r}".format(sku_text))
    if not SIGNED_RE.match(qty_text):
        raise ParseError(number, "bad quantity {!r}".format(qty_text))
    quantity = int(qty_text)
    if quantity == 0:
        raise ParseError(number, "quantity may not be zero")
    return Movement(date=date, sku=sku, quantity=quantity, note=(note or "").strip(WS), line=number)


def parse_movements(text: str, catalog: Dict[str, Product]) -> List[Movement]:
    """Parse movements.txt into a list of Movement, in file order."""
    movements = [parse_movement_line(number, raw, catalog) for number, raw in iter_lines(text)]
    check_balances(movements)
    return movements


def parse_orders(text: str, catalog: Dict[str, Product]) -> List[Order]:
    """Parse orders.txt into a list of Order, in file order."""
    orders: List[Order] = []
    seen = set()
    for number, raw in iter_lines(text):
        fields = FIELDS_RE.split(raw.strip(WS))
        if len(fields) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES, found {} fields".format(len(fields)))
        id_text, date_text, customer, lines_text = fields
        if not ORDER_RE.match(id_text):
            raise ParseError(number, "bad order number {!r}".format(id_text))
        order_id = id_text.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order {}".format(order_id))
        date = parse_date(date_text)
        if date is None:
            raise ParseError(number, "bad date {!r}".format(date_text))
        lines: List[Tuple[str, int]] = []
        skus = set()
        for item in lines_text.split(","):
            sku_text, star, qty_text = item.partition("*")
            if not star:
                raise ParseError(number, "bad order line {!r} (expected SKU*QUANTITY)".format(item))
            sku = normalize_sku(sku_text)
            if sku is None or sku not in catalog:
                raise ParseError(number, "unknown SKU {!r}".format(sku_text))
            if sku in skus:
                raise ParseError(number, "SKU {} appears more than once in the order".format(sku))
            if not WHOLE_RE.match(qty_text) or int(qty_text) < 1:
                raise ParseError(number, "bad quantity {!r}".format(qty_text))
            skus.add(sku)
            lines.append((sku, int(qty_text)))
        seen.add(order_id)
        orders.append(Order(id=order_id, date=date, customer=customer, lines=lines, line=number))
    return orders
"""Pricing an order: volume discount, order discount, per-line tax."""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import Dict, List

from .parsing import TAX_RATES, Product

PENNY = Decimal("0.01")
ZERO = Decimal("0.00")
ORDER_DISCOUNT_THRESHOLD = Decimal("500.00")


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def money(value: Decimal) -> Decimal:
    """Round half up to the penny; never return -0.00."""
    result = value.quantize(PENNY, rounding=ROUND_HALF_UP)
    if result == 0:
        return ZERO
    return result


def volume_rate(quantity: int) -> Decimal:
    if quantity >= 50:
        return Decimal("0.10")
    if quantity >= 10:
        return Decimal("0.05")
    return Decimal("0")


def allocate(discount_pennies: int, nets_pennies: List[int]) -> List[int]:
    """Share a whole number of pennies over lines in proportion to their nets.

    Each share is rounded down; the leftover pennies go one each to the lines
    with the largest remainder, the earlier line first on a tie.
    """
    total = sum(nets_pennies)
    if total == 0 or discount_pennies == 0:
        return [0] * len(nets_pennies)
    shares = []
    remainders = []
    for net in nets_pennies:
        share, remainder = divmod(discount_pennies * net, total)
        shares.append(share)
        remainders.append(remainder)
    leftover = discount_pennies - sum(shares)
    order = sorted(range(len(nets_pennies)), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        shares[i] += 1
    return shares


def price_order(order, catalog: Dict[str, Product]) -> Quote:
    """Price any object with .lines, a list of (sku, quantity) pairs."""
    lines: List[QuoteLine] = []
    for sku, quantity in order.lines:
        product = catalog[sku]
        unit = money(product.price)
        gross = money(unit * quantity)
        discount = money(-(gross * volume_rate(quantity)).quantize(PENNY, rounding=ROUND_HALF_UP))
        net = money(gross + discount)
        lines.append(QuoteLine(sku=sku, quantity=quantity, unit=unit, gross=gross, discount=discount, net=net))

    subtotal = money(sum((line.net for line in lines), ZERO))
    if subtotal >= ORDER_DISCOUNT_THRESHOLD:
        order_discount = money(-(subtotal * Decimal("0.03")).quantize(PENNY, rounding=ROUND_HALF_UP))
    else:
        order_discount = ZERO

    shares = allocate(int(-order_discount * 100), [int(line.net * 100) for line in lines])
    tax = ZERO
    for line, share in zip(lines, shares):
        taxable = line.net - Decimal(share) * PENNY
        tax += money(taxable * TAX_RATES[catalog[line.sku].tax])
    tax = money(tax)
    total = money(subtotal + order_discount + tax)
    return Quote(lines=lines, subtotal=subtotal, order_discount=order_discount, tax=tax, total=total)
"""The shelves: stock levels, history, what to buy, and adding movements."""

import datetime
import os
from typing import Dict, Iterable, List, Tuple

from .parsing import Movement, Product


def in_date_order(movements: Iterable[Movement]) -> List[Movement]:
    """Movements in the order they count: by date, same day in list order."""
    return sorted(movements, key=lambda m: m.date)


def stock_levels(catalog: Dict[str, Product], movements: Iterable[Movement]) -> Dict[str, int]:
    """Quantity on the shelf for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for m in movements:
        levels[m.sku] = levels.get(m.sku, 0) + m.quantity
    return levels


def status(onhand: int, reorder: int) -> str:
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def history(sku: str, movements: Iterable[Movement]) -> List[Tuple[Movement, int]]:
    """(movement, balance after it) for one product, in the order they count."""
    balance = 0
    rows = []
    for m in in_date_order(movements):
        if m.sku != sku:
            continue
        balance += m.quantity
        rows.append((m, balance))
    return rows


def signed(quantity: int) -> str:
    return "{:+d}".format(quantity)


def format_movement(date: datetime.date, sku: str, quantity: int, note: str = "") -> str:
    """A movement line as written to movements.txt: DATE SKU ±QTY[ NOTE]."""
    text = "{} {} {}".format(date.isoformat(), sku, signed(quantity))
    if note:
        text += " " + note
    return text


def append_lines(path: str, lines: List[str]) -> None:
    """Append lines to a file, adding a newline first if it does not end in one."""
    prefix = b""
    try:
        with open(path, "rb") as fh:
            fh.seek(0, os.SEEK_END)
            if fh.tell() > 0:
                fh.seek(-1, os.SEEK_END)
                if fh.read(1) != b"\n":
                    prefix = b"\n"
    except FileNotFoundError:
        pass
    data = prefix + "".join(line + "\n" for line in lines).encode("utf-8")
    with open(path, "ab") as fh:
        fh.write(data)
"""The orders: what has shipped, fulfilling, invoices and the report."""

import datetime
import re
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Tuple

from .parsing import Movement, Order, Product
from .pricing import Quote, price_order
from .shelves import format_movement, in_date_order


@dataclass(frozen=True)
class Shipped:
    """Something with .lines that price_order can price."""

    lines: List[Tuple[str, int]]


@dataclass(frozen=True)
class FulfilLine:
    sku: str
    shipped: int
    backordered: int


@dataclass(frozen=True)
class FulfilResult:
    lines: List[FulfilLine]
    movements: List[str]
    status: str


@dataclass(frozen=True)
class ReportRow:
    order: Order
    status: str
    ordered: int
    shipped: int
    quoted: Quote
    invoiced: Optional[Quote]


def order_note(order_id: str) -> str:
    return "order {}".format(order_id)


def shipped_so_far(order: Order, movements: Iterable[Movement]) -> Dict[str, int]:
    """Units shipped per order line (capped at the quantity ordered)."""
    note = order_note(order.id)
    sent: Dict[str, int] = {sku: 0 for sku, _ in order.lines}
    for m in movements:
        if m.quantity < 0 and m.note == note and m.sku in sent:
            sent[m.sku] += -m.quantity
    return {sku: min(qty, sent[sku]) for sku, qty in order.lines}


def order_status(order: Order, shipped: Dict[str, int]) -> str:
    if all(shipped[sku] >= qty for sku, qty in order.lines):
        return "complete"
    if all(shipped[sku] == 0 for sku, _ in order.lines):
        return "open"
    return "partial"


def available_on(sku: str, date: datetime.date, movements: Iterable[Movement]) -> int:
    """How many units of sku can leave on date without any balance going negative."""
    balance = 0
    lowest_later: Optional[int] = None
    at_date: Optional[int] = None
    for m in in_date_order(movements):
        if m.sku != sku:
            continue
        if m.date > date and at_date is None:
            at_date = balance
        balance += m.quantity
        if m.date > date:
            lowest_later = balance if lowest_later is None else min(lowest_later, balance)
    if at_date is None:
        at_date = balance
    available = at_date if lowest_later is None else min(at_date, lowest_later)
    return max(0, available)


def fulfil(order: Order, date: datetime.date, movements: List[Movement]) -> FulfilResult:
    """Work out what can ship on date. The caller writes result.movements."""
    shipped = shipped_so_far(order, movements)
    lines: List[FulfilLine] = []
    new_movements: List[str] = []
    after: Dict[str, int] = {}
    for sku, qty in order.lines:
        owed = qty - shipped[sku]
        ship = min(owed, available_on(sku, date, movements))
        if ship > 0:
            new_movements.append(format_movement(date, sku, -ship, order_note(order.id)))
        after[sku] = shipped[sku] + ship
        lines.append(FulfilLine(sku=sku, shipped=ship, backordered=owed - ship))
    return FulfilResult(lines=lines, movements=new_movements, status=order_status(order, after))


def invoice(order: Order, catalog: Dict[str, Product], movements: Iterable[Movement]) -> Optional[Quote]:
    """Price what has shipped so far, or None when nothing has."""
    shipped = shipped_so_far(order, movements)
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    if not lines:
        return None
    return price_order(Shipped(lines=lines), catalog)


def order_sort_key(order: Order):
    number = int(re.sub(r"^[A-Z]+-", "", order.id))
    return (order.date, number, order.id)


def report(orders: Iterable[Order], catalog: Dict[str, Product], movements: List[Movement]) -> List[ReportRow]:
    rows = []
    for order in sorted(orders, key=order_sort_key):
        shipped = shipped_so_far(order, movements)
        rows.append(
            ReportRow(
                order=order,
                status=order_status(order, shipped),
                ordered=sum(qty for _, qty in order.lines),
                shipped=sum(shipped.values()),
                quoted=price_order(order, catalog),
                invoiced=invoice(order, catalog, movements),
            )
        )
    return rows

"""The `stockroom` command."""

import csv
import io
import json
import os
import sys
from typing import List, Optional

from . import orders as orders_mod
from .parsing import (
    WHOLE_RE,
    Movement,
    ParseError,
    check_balances,
    normalize_sku,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_orders,
)
from .pricing import Quote
from .shelves import (
    append_lines,
    buy_quantity,
    format_movement,
    history,
    signed,
    status,
    stock_levels,
)

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (allowed positional counts, allowed options)
COMMANDS = {
    "stock": ((0,), {"--json"}),
    "low": ((0,), {"--json"}),
    "history": ((1,), {"--json"}),
    "receive": ((3, 4), set()),
    "ship": ((3, 4), set()),
    "quote": ((1,), {"--json"}),
    "fulfil": ((2,), set()),
    "invoice": ((1,), {"--json"}),
    "report": ((0,), {"--format"}),
}
RAW_COMMANDS = {"receive", "ship", "fulfil"}
FORMATS = ("text", "csv", "json")
USAGE = "usage: stockroom [--dir DIR] {stock,low,history,receive,ship,quote,fulfil,invoice,report} ..."


class UsageError(Exception):
    """Something wrong with the command line (exit 2)."""


class ReadError(Exception):
    """A file that cannot be read (exit 2)."""


class Refused(Exception):
    """A data-file mistake or refused request (exit 1)."""


class Args:
    def __init__(self):
        self.dir = "."
        self.command: Optional[str] = None
        self.positional: List[str] = []
        self.json = False
        self.format = "text"


def parse_args(argv: List[str]) -> Args:
    args = Args()
    rest: List[str] = []
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("option --dir needs a value")
            args.dir = argv[i + 1]
            i += 2
            continue
        if token.startswith("--dir="):
            args.dir = token[len("--dir="):]
            i += 1
            continue
        rest.append(token)
        i += 1
    if args.dir == "":
        raise UsageError("option --dir needs a non-empty value")

    before: List[str] = []
    after: List[str] = []
    for token in rest:
        if args.command is None and not token.startswith("-"):
            args.command = token
        elif args.command is None:
            before.append(token)
        else:
            after.append(token)
    if args.command is None:
        if before:
            raise UsageError("unknown option {}".format(before[0]))
        raise UsageError("no command given")
    if args.command not in COMMANDS:
        raise UsageError("unknown command {!r}".format(args.command))
    counts, options = COMMANDS[args.command]

    if args.command in RAW_COMMANDS:
        if before:
            raise UsageError("unknown option {}".format(before[0]))
        args.positional = after
    else:
        tokens = before + after
        j = 0
        while j < len(tokens):
            token = tokens[j]
            if token.startswith("-") and token != "-":
                if token == "--json" and "--json" in options:
                    args.json = True
                elif token == "--format" and "--format" in options:
                    if j + 1 >= len(tokens):
                        raise UsageError("option --format needs a value")
                    args.format = tokens[j + 1]
                    j += 1
                    if args.format not in FORMATS:
                        raise UsageError("bad value for --format: {!r} (text, csv or json)".format(args.format))
                elif token.startswith("--format=") and "--format" in options:
                    args.format = token[len("--format="):]
                    if args.format not in FORMATS:
                        raise UsageError("bad value for --format: {!r} (text, csv or json)".format(args.format))
                else:
                    raise UsageError("unknown option {} for {}".format(token, args.command))
            else:
                args.positional.append(token)
            j += 1

    if len(args.positional) not in counts:
        raise UsageError("wrong number of arguments for {}".format(args.command))
    if args.command in ("receive", "ship", "fulfil"):
        date_text = args.positional[0] if args.command != "fulfil" else args.positional[1]
        if parse_date(date_text) is None:
            raise UsageError("bad date {!r} (expected YYYY-MM-DD)".format(date_text))
    return args


class Files:
    """Reads the data files of one folder."""

    def __init__(self, folder: str):
        if not os.path.isdir(folder):
            raise ReadError("{}: no such directory".format(folder))
        self.folder = folder

    def path(self, name: str) -> str:
        return os.path.join(self.folder, name)

    def text(self, name: str) -> str:
        try:
            with open(self.path(name), "rb") as fh:
                data = fh.read()
        except FileNotFoundError:
            if name == CATALOG:
                raise ReadError("{}: file not found".format(name))
            data = b""
        except OSError as exc:
            raise ReadError("{}: {}".format(name, exc.strerror or exc))
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ReadError("{}: not valid UTF-8 (byte {})".format(name, exc.start))


def load(files: Files, need_movements: bool, need_orders: bool):
    """Read then parse the needed files; returns (catalog, movements, orders)."""
    catalog_text = files.text(CATALOG)
    movements_text = files.text(MOVEMENTS) if need_movements else None
    orders_text = files.text(ORDERS) if need_orders else None
    name = CATALOG
    try:
        catalog = parse_catalog(catalog_text)
        movements = None
        orders = None
        if movements_text is not None:
            name = MOVEMENTS
            movements = parse_movements(movements_text, catalog)
        if orders_text is not None:
            name = ORDERS
            orders = parse_orders(orders_text, catalog)
    except ParseError as exc:
        raise Refused("{}: {}".format(name, exc))
    return catalog, movements, orders


def dump_json(obj) -> str:
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


def find_order(order_list, text: str):
    wanted = text.upper()
    for order in order_list:
        if order.id == wanted:
            return order
    raise Refused("{}: unknown order {}".format(ORDERS, text))


def quote_text(header: str, quote: Quote) -> str:
    out = [header]
    for ln in quote.lines:
        out.append("{} {} {} {} {} {}".format(ln.sku, ln.quantity, ln.unit, ln.gross, ln.discount, ln.net))
    out.append("subtotal {}".format(quote.subtotal))
    out.append("order discount {}".format(quote.order_discount))
    out.append("tax {}".format(quote.tax))
    out.append("total {}".format(quote.total))
    return lines_out(out)


def quote_json(order, quote: Quote) -> str:
    return dump_json(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": ln.sku,
                    "quantity": ln.quantity,
                    "unit": str(ln.unit),
                    "gross": str(ln.gross),
                    "discount": str(ln.discount),
                    "net": str(ln.net),
                }
                for ln in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        }
    )


def cmd_stock(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        p = catalog[sku]
        rows.append({"sku": sku, "name": p.name, "onhand": levels[sku], "status": status(levels[sku], p.reorder)})
    if args.json:
        return dump_json(rows)
    return lines_out(["{} {} {} {}".format(r["sku"], r["onhand"], r["status"], r["name"]) for r in rows])


def cmd_low(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        p = catalog[sku]
        onhand = levels[sku]
        if status(onhand, p.reorder) in ("low", "out"):
            rows.append({"sku": sku, "onhand": onhand, "reorder": p.reorder, "buy": buy_quantity(onhand, p.reorder)})
    if args.json:
        return dump_json(rows)
    return lines_out(["{} {} {} {}".format(r["sku"], r["onhand"], r["reorder"], r["buy"]) for r in rows])


def cmd_history(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    sku = normalize_sku(args.positional[0])
    if sku is None or sku not in catalog:
        raise Refused("{}: unknown SKU {}".format(CATALOG, args.positional[0]))
    rows = history(sku, movements)
    if args.json:
        return dump_json(
            [
                {"date": m.date.isoformat(), "delta": signed(m.quantity), "balance": bal, "note": m.note}
                for m, bal in rows
            ]
        )
    out = []
    for m, bal in rows:
        text = "{} {} {}".format(m.date.isoformat(), signed(m.quantity), bal)
        if m.note:
            text += " " + m.note
        out.append(text)
    return lines_out(out)


def cmd_move(args: Args, files: Files) -> str:
    catalog, movements, _ = load(files, True, False)
    date_text, sku_text, qty_text = args.positional[:3]
    note = args.positional[3] if len(args.positional) == 4 else ""
    date = parse_date(date_text)
    sku = normalize_sku(sku_text)
    if sku is None or sku not in catalog:
        raise Refused("{}: unknown SKU {}".format(CATALOG, sku_text))
    if not WHOLE_RE.match(qty_text) or int(qty_text) == 0:
        raise Refused("bad quantity {!r}: must be a whole number of one or more".format(qty_text))
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    note = note.strip(" \t")
    quantity = int(qty_text) if args.command == "receive" else -int(qty_text)
    new = Movement(date=date, sku=sku, quantity=quantity, note=note, line=0)
    try:
        check_balances(list(movements) + [new])
    except ParseError as exc:
        if exc.line == 0:
            raise Refused("{}: refused: stock of {} would go below zero".format(MOVEMENTS, sku))
        raise Refused(
            "{}: refused: stock of {} would go below zero at line {}".format(MOVEMENTS, sku, exc.line)
        )
    line = format_movement(date, sku, quantity, note)
    write(files, [line])
    return lines_out([line])


def write(files: Files, lines: List[str]) -> None:
    try:
        append_lines(files.path(MOVEMENTS), lines)
    except OSError as exc:
        raise ReadError("{}: {}".format(MOVEMENTS, exc.strerror or exc))


def cmd_quote(args: Args, files: Files) -> str:
    catalog, _, order_list = load(files, False, True)
    order = find_order(order_list, args.positional[0])
    quote = orders_mod.price_order(order, catalog)
    if args.json:
        return quote_json(order, quote)
    return quote_text("{} {} {}".format(order.id, order.date.isoformat(), order.customer), quote)


def cmd_fulfil(args: Args, files: Files) -> str:
    catalog, movements, order_list = load(files, True, True)
    order = find_order(order_list, args.positional[0])
    date = parse_date(args.positional[1])
    if date < order.date:
        raise Refused(
            "refused: {} is before the date of order {} ({})".format(date.isoformat(), order.id, order.date.isoformat())
        )
    result = orders_mod.fulfil(order, date, movements)
    if result.movements:
        write(files, result.movements)
    out = ["{} shipped {} backordered {}".format(ln.sku, ln.shipped, ln.backordered) for ln in result.lines]
    out.append("status {}".format(result.status))
    return lines_out(out)


def cmd_invoice(args: Args, files: Files) -> str:
    catalog, movements, order_list = load(files, True, True)
    order = find_order(order_list, args.positional[0])
    quote = orders_mod.invoice(order, catalog, movements)
    if quote is None:
        raise Refused("refused: nothing has shipped for order {} yet".format(order.id))
    if args.json:
        return quote_json(order, quote)
    return quote_text("invoice {} {} {}".format(order.id, order.date.isoformat(), order.customer), quote)


def cmd_report(args: Args, files: Files) -> str:
    catalog, movements, order_list = load(files, True, True)
    rows = []
    for r in orders_mod.report(order_list, catalog, movements):
        rows.append(
            {
                "order": r.order.id,
                "date": r.order.date.isoformat(),
                "customer": r.order.customer,
                "status": r.status,
                "ordered": r.ordered,
                "shipped": r.shipped,
                "quoted": str(r.quoted.total),
                "invoiced": str(r.invoiced.total) if r.invoiced else "0.00",
            }
        )
    if args.format == "json":
        return dump_json(rows)
    if args.format == "csv":
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buf.getvalue()
    return lines_out(
        [
            "{} {} {} {} {}/{} {} {}".format(
                r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"]
            )
            for r in rows
        ]
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move,
    "ship": cmd_move,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def emit(text: str) -> None:
    buffer = getattr(sys.stdout, "buffer", None)
    if buffer is not None:
        sys.stdout.flush()
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        sys.stdout.write(text)
        sys.stdout.flush()


def error(message: str) -> None:
    text = "stockroom: {}\n".format(message)
    buffer = getattr(sys.stderr, "buffer", None)
    if buffer is not None:
        sys.stderr.flush()
        buffer.write(text.encode("utf-8", "backslashreplace"))
        buffer.flush()
    else:
        sys.stderr.write(text)
        sys.stderr.flush()


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        args = parse_args(list(argv))
        files = Files(args.dir)
        output = HANDLERS[args.command](args, files)
    except UsageError as exc:
        error(str(exc))
        sys.stderr.write(USAGE + "\n")
        return 2
    except ReadError as exc:
        error(str(exc))
        return 2
    except Refused as exc:
        error(str(exc))
        return 1
    try:
        emit(output)
    except BrokenPipeError:
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError, io.UnsupportedOperation):
            pass
        return 0
    return 0
